using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using AForge.Video.FFMPEG;
using System.Drawing;

namespace TekstDuplikationsfjernelsesværktøj
{
    class AForgeNetHelper
    {
        public void AddTransitionEffect(string videoFilenameIn, string videoFilenameOut, int effectDuration, string effectType)
        {
            // Læser den indgående videofil
            VideoFileReader reader = new VideoFileReader();
            reader.Open(videoFilenameIn);

            // Åbner videowriteren
            VideoFileWriter writer = new VideoFileWriter();
            writer.Open(videoFilenameOut, reader.Width, reader.Height, reader.FrameRate, VideoCodec.MPEG4);

            // Henter det første videobillede og kopierer det til bufferen
            Bitmap prevFrame = reader.ReadVideoFrame();
            Bitmap currFrame = null;

            // Gennemløber alle billeder og tilføjer overgangseffekter
            for (int i = 1; i < reader.FrameCount; i++)
            {
                currFrame = reader.ReadVideoFrame();

                if (i <= effectDuration)
                {
                    // Tilføjer overgangseffekt
                    if (effectType == "Fade")
                    {
                        FadingEffect(prevFrame, currFrame, i, effectDuration);
                    }
                    else if (effectType == "Blend")
                    {
                        BlendingEffect(prevFrame, currFrame, i, effectDuration);
                    }
                }

                // Skriver det behandlede billede til filen
                writer.WriteVideoFrame(currFrame);

                // Frigør bufferen
                prevFrame.Dispose();
                prevFrame = (Bitmap)currFrame.Clone();
                currFrame.Dispose();
            }

            // Skriver det sidste billede til filen
            writer.WriteVideoFrame(prevFrame);

            // Frigør ressourcer
            reader.Close();
            writer.Close();
        }

        private void FadingEffect(Bitmap prevFrame, Bitmap currFrame, int frameIndex, int maxFrame)
        {
            // Beregner transparens
            float alpha = (float)frameIndex / (float)maxFrame;

            // Fade-effekt
            currFrame = CombineImages(prevFrame, currFrame, alpha);
        }

        private void BlendingEffect(Bitmap prevFrame, Bitmap currFrame, int frameIndex, int maxFrame)
        {
            // Beregner blandingskoefficient
            float weight = (float)frameIndex / (float)maxFrame;

            // Blander de to billeder baseret på blandingskoefficienten
            currFrame = BlendImages(prevFrame, currFrame, weight);
        }

